import json, sys, statistics
from collections import defaultdict

sys.path.insert(0, r"D:\DevOpsAutopilot\video-31-ai-cost\cost-desk")
from pricing import cost_usd, prompt_tokens

def load(p):
    return [json.loads(l) for l in open(p, encoding="utf-8") if l.strip()]

v1 = load(sys.argv[1]); v3 = load(sys.argv[2])

for r in v1:
    if r["usage"] is None:
        continue
    c, lp = cost_usd(r["model"], r["usage"])
    if abs(c - r["cost_usd"]) > 1e-9 or lp != r["long_prompt"]:
        print("MISMATCH", r["user"], r["feature"], r["cost_usd"], c, lp, r["usage"])

def q(xs):
    xs = sorted(xs)
    return f"n={len(xs)} min={xs[0]} p50={xs[len(xs)//2]} p90={xs[int(len(xs)*.9)]} max={xs[-1]}"

for name, rows in (("v1", v1), ("v3", v3)):
    print(f"\n== {name} prompt tokens by feature ==")
    by = defaultdict(list)
    for r in rows:
        if r["usage"]:
            by[r["feature"]].append(prompt_tokens(r["usage"]))
    for f, xs in by.items():
        print(f"  {f:9} {q(xs)}")
    big = [r for r in rows if r["usage"] and prompt_tokens(r["usage"]) > 50_000]
    for r in big:
        u = r["usage"]
        print(f"  >50k: {r['user']} {r['feature']} {r['model']} in={u['input_tokens']} cr={u['cache_read_input_tokens']} out={u['output_tokens']} long={r['long_prompt']} cost={r['cost_usd']:.5f}")
    tot = defaultdict(float)
    for r in rows:
        if r["user"] != "smoke":
            tot[r["user"]] += r["cost_usd"]
    med = statistics.median(tot.values())
    print(f"  median user ${med:.5f}; u55 ${tot['u55']:.5f} = {tot['u55']/med:.1f}x; total ${sum(tot.values()):.4f}")
    # chat: per-user mean prompt tokens per turn
    chat = defaultdict(list)
    for r in rows:
        if r["feature"] == "chat" and r["usage"]:
            chat[r["user"]].append(prompt_tokens(r["usage"]))
    s = sorted(((statistics.mean(v), u, len(v)) for u, v in chat.items()), reverse=True)
    print("  chat mean prompt/turn top:", [(u, int(m), n) for m, u, n in s[:5]], "median user:", int(statistics.median(m for m, _, _ in s)))

u55v3 = [r for r in v3 if r["user"] == "u55"]
print("\n== u55 in v3 ==")
for r in sorted(u55v3, key=lambda r: r["ts"])[:4]:
    u = r["usage"] or {}
    print(f"  {r['feature']:9} {r['model']} in={u.get('input_tokens')} cr={u.get('cache_read_input_tokens')} cw5={u.get('cache_write_5m')} out={u.get('output_tokens')} long={r['long_prompt']} cost={r['cost_usd']:.5f}")
